// === EMBEDDED DATA ===
const ARK_GUIDES = [
  {slug:'water-safety',category:'water',title:'Drinking water in an outage',updated:'2024-01',summary:'How much to store, exactly how to treat water you are unsure about, and when treating is pointless.',seeAlso:['water-purification','sanitation-no-water'],quickSteps:['Store at least 1 gallon (about 4 litres) per person per day for drinking and sanitation. Three days minimum, two weeks if you can.','Boil uncertain water at a rolling boil for 1 minute, or 3 minutes above roughly 6,500 ft (2,000 m). Let it cool covered before drinking.','If told to disinfect with bleach: 8 drops (about 1/8 teaspoon) of unscented 5–8.25% chlorine bleach per gallon of clear water, 16 drops if cloudy, then wait 30 minutes. It should smell faintly of chlorine.','A do-not-drink notice is different from a boil notice. If the warning is chemical, boiling concentrates it. Use bottled water or another source instead.','Never drink from radiators, hot-water heating systems, swimming pools, spas or water beds.'],sections:[{heading:'Fill up before the pressure drops',body:['Fill clean containers, the bathtub and any food-grade buckets while pressure is still available. Label each with the date and rotate stored water every six months.','A bathtub of water is for washing and flushing, not for drinking, unless you have a food-grade liner and treat it first.']},{heading:'Boiling beats everything else',body:['Boiling is the most reliable method against bacteria, viruses and parasites. A rolling boil for one minute is enough at low altitude; add two minutes above 6,500 ft.','Boiling does not remove chemicals, salt or heavy metals. If you suspect those, use bottled water or a filter certified for them.']},{heading:'Filters, tablets and bleach',body:['Use a filter rated for the contaminants you are worried about. Many camping filters handle bacteria and protozoa but not viruses; boiling or chemical treatment covers that gap.','Chlorine dioxide or iodine tablets need the contact time on the label, usually 30 minutes or more, and colder water needs longer.']},{heading:'Sanitation matters as much as drinking',body:['Reserve water for handwashing before meals and after using the toilet. Hand hygiene prevents more illness in a prolonged outage than any water treatment upgrade.','If plumbing fails, follow your local health department instructions for waste.']}],sources:[{label:'Ready.gov — Water',url:'https://www.ready.gov/water'},{label:'CDC — Make water safe during an emergency',url:'https://www.cdc.gov/water-emergency'},{label:'EPA — Emergency disinfection',url:'https://www.epa.gov/ground-water-and-drinking-water/emergency-disinfection-drinking-water'}]},
  {slug:'water-purification',category:'water',title:'Water purification in the field',updated:'2024-01',summary:'How to make water safe from streams, rain, ponds or unknown sources using what you have.',seeAlso:['water-safety','foraging'],quickSteps:['Never drink untreated surface water — even clear mountain streams can carry Giardia and Cryptosporidium.','Boiling is the most reliable: a full rolling boil for 1 minute (3 minutes above 6,500 ft/2,000 m). Let cool in a covered container.','If boiling is not possible, use iodine or chlorine dioxide tablets per the label — usually 30 min contact time; double in cold or cloudy water.','Portable filters (0.1–0.2 micron) remove bacteria and protozoa but NOT viruses. Combine with chemical treatment in areas with human sewage.','Solar disinfection (SODIS): fill a clear PET bottle, lay it in direct sunlight for at least 6 hours on a mostly sunny day, or 2 full days in a row if the sky is more than half cloudy. Use clear water in bottles of 2 litres or less; it does not work during continuous rain. Effective against bacteria and viruses.'],sections:[{heading:'Improvised filtration before purification',body:['Filtering first removes particles that protect pathogens from chemical treatment. Layer grass, crushed charcoal (not briquettes) and sand in a container with small holes — coarsest material first (grass), finest last (sand/charcoal).','This is pre-treatment only, not purification. Always follow with boiling or chemical treatment.','Let filtered water settle 30 minutes and decant the clear top before treating.']},{heading:'Disinfection by chemical method',body:['Household unscented bleach (5–8.25% sodium hypochlorite): 8 drops per gallon of clear water, 16 drops if cloudy. Wait 30 minutes. Water should have a faint chlorine smell; if not, repeat the dose and wait 15 more minutes.','Iodine tablets or chlorine dioxide tablets follow label instructions — usually 1 tablet per litre; 30–60 minutes contact time.','Chemical methods are less effective against Cryptosporidium — boiling or a 1-micron absolute filter is preferred for that.']},{heading:'Collecting and storing clean water',body:['Rain collection from roof or tarp is relatively clean — discard the first few minutes of runoff to flush contaminants.','Store treated water in food-grade, opaque containers with tight lids. Keep out of sunlight to prevent algae and reduce chlorine loss.','Label the date. Treated water stored properly stays safe about 6 months.']}],sources:[{label:'CDC — Water purification',url:'https://www.cdc.gov/healthywater/emergency/making-water-safe.html'},{label:'WHO — SODIS',url:'https://www.who.int/publications/m/item/sodis-manual'},{label:'EPA — Emergency disinfection',url:'https://www.epa.gov/ground-water-and-drinking-water/emergency-disinfection-drinking-water'}]},
  {slug:'food-safety',category:'food',title:'Keeping food safe without power',updated:'2024-01',summary:'The exact time and temperature limits, and how to decide what to throw out without guessing.',seeAlso:['foraging','water-safety'],quickSteps:['Keep the refrigerator and freezer closed. A closed refrigerator holds food safe for about 4 hours. A full freezer holds about 48 hours; a half-full one about 24.','Throw out perishable food that has been above 40°F (4°C) for more than 2 hours.','Never taste food to decide whether it is safe. Pathogens do not change smell, colour or texture.','Refreeze food only if it still contains ice crystals or is at or below 40°F.','Never burn charcoal, a camping stove or a generator indoors — carbon monoxide kills.'],sections:[{heading:'Make the cold last',body:['Group frozen items together and fill gaps with frozen water bottles or a block of ice. A full freezer stays cold far longer than a half-empty one.','Keep a thermometer in the refrigerator and freezer so you can read the temperature instead of guessing.']},{heading:'A cooler is a second freezer',body:['Keep raw meat below ready-to-eat food, and keep ice in sealed containers so meltwater does not contaminate anything.','Check the cooler temperature. If it rises above 40°F for more than 2 hours, treat the contents as spoiled.']},{heading:'Eating well without cooking',body:['Plan for meals that need no heat: canned beans and fish, nut butters, crackers, shelf-stable milk, dried fruit. Keep a manual can opener with the food.','Rotate the pantry every six months and eat what you store, so nothing in the kit is unfamiliar when it matters.']}],sources:[{label:'FoodSafety.gov',url:'https://www.foodsafety.gov/food-safety-charts/food-safety-during-power-outage'},{label:'USDA FSIS',url:'https://www.fsis.usda.gov'}]},
  {slug:'sanitation-no-water',category:'water',title:'Toilets and waste when water fails',updated:'2024-01',summary:'Keeping waste away from people, water and food when the plumbing stops working.',seeAlso:['water-safety','water-purification'],quickSteps:['Stop flushing once you know pressure is lost. Each flush wastes several gallons you may need.','Line the toilet bowl with a double plastic bag, use it, then cover with sawdust, cat litter or shredded paper and seal when about half full.','Keep waste at least 100 feet (30 m) from wells, streams, ditches and house foundations.','Wash hands with soap and treated water after every contact.','Follow your local health department instructions as soon as they publish any.'],sections:[{heading:'Set up before it is urgent',body:['Store heavy-duty bags, gloves, a lidded bucket, disinfectant and paper towels with the rest of the kit.','Decide in advance where the emergency toilet goes: away from food, sleeping areas and any water source.']},{heading:'Keep it separate',body:['Designate one container as the toilet and never use it for anything else. Keep a lid on it and keep it outside the main living space if you can.','People who are ill, pregnant, very young or immunocompromised should have the cleanest available option.']}],sources:[{label:'CDC — Sanitation in emergencies',url:'https://www.cdc.gov/sanitation/'},{label:'Ready.gov',url:'https://www.ready.gov/sanitation'}]},
  {slug:'generator-carbon-monoxide',category:'power',title:'Generators and carbon monoxide',updated:'2024-01',summary:'Carbon monoxide is invisible and kills whole households. Placement matters more than generator size.',seeAlso:['power-outage-prep','shelter-building'],quickSteps:['Run a generator outdoors only, at least 20 feet (6 m) from doors, windows and vents, with the exhaust pointing away from the building.','Never run one in a garage, basement, crawlspace, attached carport or porch, even with the door open.','Keep working carbon monoxide alarms on every level of the home and outside sleeping areas, and test them monthly.','If anyone has a headache with dizziness, nausea, weakness, chest pain or confusion, get everyone into fresh air and call 911.','Never plug a generator into a wall outlet — that backfeeds the utility line and can kill a line worker.'],sections:[{heading:'Why proximity is the whole problem',body:['Carbon monoxide from a generator can seep through a window, a vent or a wall opening even when the unit sits outside. Twenty feet with the exhaust directed away is the minimum.','Smaller spaces are more dangerous: a garage or a tent concentrates the gas. Every year people die running generators in exactly those places.']},{heading:'Alarms and detection',body:['A carbon monoxide alarm is the only reliable warning. Replace the unit by the date on the back even if it still beeps when tested.','Do not rely on the smell of exhaust. Carbon monoxide has no smell.']}],sources:[{label:'CDC — Carbon monoxide prevention',url:'https://www.cdc.gov/carbon-monoxide'},{label:'CPSC — Generator safety',url:'https://www.cpsc.gov'}]},
  {slug:'power-outage-prep',category:'power',title:'Preparing for a long power outage',updated:'2024-01',summary:'What to unplug, what to keep running, and how to make a battery last several days.',seeAlso:['generator-carbon-monoxide','communication-failure','radio-comms'],quickSteps:['Charge phones, battery banks, medical devices and any power wheelchair as soon as a warning is issued.','Keep one light, one radio and one charging method per person, and know where they are in the dark.','Unplug computers, televisions and appliances before power returns, to avoid surge damage.','Keep cash in small notes — card readers, cash machines and fuel pumps may all be down at the same time.','Report downed power lines to the utility or 911 from a safe distance.'],sections:[{heading:'Making a battery last',body:['Put phones in airplane mode, cut brightness, and turn off background sync. A phone in airplane mode can last several times longer.','Charge one device at a time from a battery bank instead of leaving several plugged in and half-charged.']},{heading:'When power returns',body:['Check the refrigerator and freezer temperatures, reset clocks and alarms, and confirm smoke and carbon monoxide alarms still work.','Bring systems back gradually, and watch for any burning smell or sparking.']}],sources:[{label:'Ready.gov — Power outages',url:'https://www.ready.gov/power-outages'}]},
  {slug:'extreme-heat-cold',category:'weather',title:'Extreme heat and cold',updated:'2024-01',summary:'Recognising the point where heat or cold becomes an emergency, and using the safest space you actually have.',seeAlso:['shelter-building','first-aid','water-safety'],quickSteps:['Confusion, fainting, hot dry skin or a dangerously high body temperature in heat is an emergency. Call 911 and cool the person while you wait.','In cold, unstoppable shivering, slurred speech, clumsiness or drowsiness suggests hypothermia. Get the person dry, warm the body slowly, and call for help.','Never leave anyone in a parked vehicle in heat or cold, and never use a stove, oven or grill to heat a home.','Check on people living alone, older adults, infants and anyone with a chronic illness. They are at highest risk.','Drink water before you feel thirsty. In heat, avoid alcohol and heavy exertion in the middle of the day.'],sections:[{heading:'Heat: act early',body:['Heat illness escalates from cramps and heavy sweating to exhaustion, then confusion and collapse. Stop activity at the first cramps and move to shade or a cooler room.','Use shade, wet cloths on the neck and wrists, and moving air.']},{heading:'Cold: warm the body, not the room',body:['Layer clothing, stay dry, and cover the head and hands. Wet clothing loses heat far faster than dry clothing.','Warm a hypothermic person gradually with blankets and body heat. Do not give alcohol, do not rub the skin.']}],sources:[{label:'National Weather Service — Heat safety',url:'https://www.weather.gov/safety/heat'},{label:'CDC — Heat and health',url:'https://www.cdc.gov/heat-health/'}]},
  {slug:'evacuation-sheltering',category:'evacuation',title:'Evacuation and sheltering in place',updated:'2024-01',summary:'When to go, when to stay put, and what to take if you have two minutes.',seeAlso:['communication-failure','shelter-building','water-safety'],quickSteps:['If an official evacuation order covers your area, leave. Follow the route authorities give, even if it looks longer.','Never walk or drive into floodwater. Six inches of moving water can knock an adult down, and twelve inches can float a car.','If told to shelter in place, go inside, close windows and outside ventilation, and take your kit to an interior room.','Take identification, medication, water, chargers, a battery radio and your written contact card.','Never shelter in a closed attic during a flood. You can be trapped. Go to the highest floor that still has a way out.'],sections:[{heading:'Leaving well',body:['Tell your out-of-area contact where you are going and when you left.','Shut off utilities only if authorities tell you to.']},{heading:'Returning',body:['Do not return until authorities say the area is safe. Photograph damage before you move anything.','Assume downed lines are live and report them from a distance.']}],sources:[{label:'Ready.gov — Evacuation',url:'https://www.ready.gov/evacuation'},{label:'FEMA',url:'https://www.ready.gov/be-informed'}]},
  {slug:'medical-escalation',category:'medical',title:'Medical emergencies and escalation',updated:'2024-01',summary:'What to say, what to have ready, and which signs mean call immediately rather than wait.',seeAlso:['first-aid','trauma-care'],quickSteps:['Call 911 for chest pain, difficulty breathing, sudden weakness or drooping on one side, a seizure, severe bleeding, a severe allergic reaction, or anyone unresponsive.','Follow the dispatcher exactly. They can talk you through what to do while help travels.','For suspected poisoning, call Poison Control at 1-800-222-1222, or 911 if unconscious.','Apply firm, continuous pressure to a bleeding wound with a clean cloth. Do not keep lifting it to check.','Do not move someone with a suspected spinal injury unless in immediate danger.'],sections:[{heading:'Signs that mean call now',body:['Stroke: face drooping, arm weakness, speech difficulty, sudden loss of balance or vision. Note the time symptoms started.','Heart attack: chest pressure, pain to arm/jaw/back, shortness of breath, cold sweat. Call first.','Severe allergic reaction: swelling of face or throat, difficulty breathing, widespread hives. Use prescribed epinephrine if available, then call 911.']},{heading:'Have this ready to read out',body:['A written list of every medication, dose and prescriber, plus allergies, conditions and any implant.','At least seven days of prescription medication in the go-bag, and phone numbers of prescriber and pharmacy.']}],sources:[{label:'American Red Cross',url:'https://www.redcross.org'},{label:'Poison Control',url:'https://poison.org/'}]},
  {slug:'communication-failure',category:'communication',title:'When phones and internet fail',updated:'2024-01',summary:'A plan that works on paper, without apps, accounts or signal.',seeAlso:['radio-comms','family-reunification','signaling-rescue'],quickSteps:['Agree in advance on one out-of-area contact, one check-in time, and two meeting places. Write them down for every household member.','Send short text messages instead of calling when the network is congested. Texts queue and often arrive when a call cannot get through.','Conserve battery: airplane mode, lowest brightness, and the phone off between agreed check-in windows.','Give every person a printed card with the out-of-area contact, meeting points, and allergies or medication a responder would need.','Do not assume a message arrived. Silence is not confirmation that someone is safe.'],sections:[{heading:'Why out-of-area contacts work',body:['Local towers and lines saturate first. A contact in another region is often reachable when everyone nearby is not.','Tell that contact the plan now, while nothing is wrong, so they know what to expect.']},{heading:'What ARK can and cannot do',body:['In a crisis, ARK makes its own internet from the devices around you. One laptop (or a Raspberry Pi) runs the ARK Hub. Nearby phones join it over Wi-Fi. Hubs pass messages on to each other over a network link, by radio, or on a USB stick.','This network is local. Messages reach people on your hub and on the hubs linked to it. They do not reach the wider internet or emergency services, and nobody monitors ARK.','A phone alone cannot be the hub. With no hub nearby, the guides and your plan still work on this phone, and messages wait until you join a hub.','Keep paper and the equipment you already own as the dependable path. ARK is an extra layer, not the base layer.']}],sources:[{label:'Ready.gov — Make a plan',url:'https://www.ready.gov/plan'}]},
  {slug:'family-reunification',category:'reunification',title:'Finding each other again',updated:'2024-01',summary:'Meeting points, school and care procedures, and how to report someone missing.',seeAlso:['communication-failure','signaling-rescue'],quickSteps:['Use the two meeting points in your household plan: one just outside the home, one outside the neighbourhood.','Know your school or care provider\'s written reunification procedure and confirm who is authorised to collect each person.','Go to the agreed meeting point and stay long enough to be found. Leave a written note at home saying where you went and when.','To report someone missing, contact local authorities with a recent photo, what they were wearing, and where last seen.','Tell your out-of-area contact when everyone is accounted for.'],sections:[{heading:'Set it up now',body:['Write down who collects each child and a backup, and confirm the care setting will only release a child to those people.','Children should know two things cold: the meeting place, and the out-of-area contact\'s number. Practice saying the number out loud.']}],sources:[{label:'Ready.gov',url:'https://www.ready.gov/plan'},{label:'NCMEC',url:'https://www.missingkids.org'}]},
  {slug:'community-assistance',category:'community',title:'Helping neighbours without creating harm',updated:'2024-01',summary:'How to organise local help, protect vulnerable people, and avoid becoming a second emergency.',seeAlso:['communication-failure','family-reunification'],quickSteps:['Work through an identified coordinator and a staffed, safe location wherever one exists.','Share needs, not identities. Never publish a vulnerable person\'s address, condition or location on a public board.','Only accept tasks you are trained and equipped for. Untrained volunteers should not do medical care, electrical work or security duties.','Offer a paper route for people with no phone, no account or no identification.','Do not send volunteers into damaged buildings, floodwater, or areas under an evacuation order.'],sections:[{heading:'Matching help to need',body:['Confirm with the person that help actually arrived. A claimed delivery is not a delivery, and in a crisis the difference matters.','Keep a written record of who received what, so recovery support can be targeted and effort is not duplicated.']},{heading:'Protecting people',body:['Set one route for concerns about a volunteer or a request, and name one person responsible for acting on them.','Never ask for or record bank details, passwords or identity documents as part of informal aid.']}],sources:[{label:'Ready.gov — Volunteering',url:'https://www.ready.gov/volunteer'},{label:'FEMA',url:'https://www.fema.gov/how-you-can-help'}]},
  {slug:'fire-starting',category:'fire',title:'Starting a fire in an emergency',updated:'2024-01',summary:'How to reliably start a fire for warmth, signaling or cooking when you have limited tools.',seeAlso:['shelter-building','signaling-rescue'],quickSteps:['Choose a sheltered site away from overhanging branches, dry grass and structures. Clear a 3-foot ring of debris.','Build a fire lay before igniting: tinder (dry grass, birch bark, shredded material) → kindling (pencil-thin sticks) → fuel (thumb-thick and larger wood). Do not skip steps.','With a lighter or matches, ignite the tinder at the base of the structure and feed air gently — blow at the base, not the top.','If you have a ferro rod: scrape firmly and quickly at a low angle. Hold tinder close. Practice the motion before you need it.','Maintain the fire with graduated fuel additions. A fire that dies from too little air or too much wet wood wastes your effort.'],sections:[{heading:'Three methods when matches are wet or absent',body:['Magnification: a convex lens (reading glasses, water-filled bag, clear bottle) focused on tinder in direct sunlight. Hold steady until smoke appears, then blow gently into a bundle.','Friction — bow drill: requires a dry softwood board (cedar, willow, cottonwood), a spindle, a bow and tinder nest. This takes practice. If you have never done it, start with the lens method.','Flint and steel: strike the flint at a sharp angle against high-carbon steel. Direct sparks onto a char cloth or dry fungus. Without char cloth, success is rare.']},{heading:'Fire in wet conditions',body:['Stand-dead wood (dead branches still on the tree) is drier than wood on the ground. Split wood exposes the drier interior.','Build a dry platform of thick logs before laying the tinder to keep the fire off wet ground.','Birch bark and pine resin ignite even when damp. Pine knot — resin-saturated heartwood — burns intensely.']},{heading:'Fire safety and extinguishing',body:['Never leave a fire unattended. Keep water or a pile of dirt nearby.','To extinguish: pour water on all embers, stir, pour again. Repeat until steam stops rising. Coals can reignite hours later.','In a survival signal fire: build it high and open. Add green or wet leaves to produce thick white smoke (visible against dark forest). Oil or rubber produces black smoke (visible against snow or a pale sky).']}],sources:[{label:'USFS — Campfire safety',url:'https://www.fs.usda.gov/detail/r1/recreation/?cid=stelprdb5399668'},{label:'Boy Scouts of America — Fire building',url:'https://www.scouting.org'}]},
  {slug:'shelter-building',category:'shelter',title:'Building an emergency shelter',updated:'2024-01',summary:'How to build a shelter that keeps body heat in and weather out, using natural or found materials.',seeAlso:['fire-starting','extreme-heat-cold'],quickSteps:['Prioritise shelter over food and fire if conditions are wet and cold — hypothermia kills in hours.','Choose a site on high ground, away from drainages and dead trees (widow-makers). Check overhead for branches before lying down.','Size matters: a small shelter is warmer. The space inside only needs to hold your body. Bigger sheds more heat.','Insulation from the ground is as important as insulation from above — 4 inches (10 cm) of dry leaves or debris under you.','Finish building while you still have energy and daylight. A rough shelter completed early beats a perfect one started in the dark.'],sections:[{heading:'Debris hut — no tools needed',body:['Find or prop a ridgepole 9 feet (2.7 m) long at chest height on one end (use a forked branch or rock), tapering to the ground on the other.','Lean branches against both sides of the ridge to form ribs, then pile debris (dry leaves, pine needles, bark) 2–3 feet (60–90 cm) thick on the outside.','Stuff the interior with dry leaves for insulation. Plug the entrance with a bundle of leaves or a backpack.','In rain, the debris must be thick enough that you can bury your arm in it and not feel the ridgepole.']},{heading:'Tarp or emergency blanket shelter',body:['A reflective emergency blanket (space blanket) increases radiated heat retention significantly. Carry one.','Ridgeline tie-off: tie a cord between two trees at chest height. Drape the tarp over and anchor the corners low to the ground. This diverts rain to the sides.','Angle the opening away from wind. Keep the pitch steep so rain runs off quickly.']},{heading:'Snow shelter',body:['In deep dry snow: dig into a slope or mound snow and pack it. Wait 20 minutes for it to sinter (harden), then hollow out. Temperature inside stays near 32°F/0°C regardless of outside cold.','Poke a ventilation hole in the ceiling with a stick or pole. CO2 and melt-water are the main hazards.','Mark the shelter with a ski pole or branch so rescuers can find it and so you can find the entrance after a storm.']}],sources:[{label:'NOLS — Wilderness medicine',url:'https://www.nols.edu'},{label:'US Army Survival Manual FM 21-76',url:'https://www.fm21-76.com'}]},
  {slug:'first-aid',category:'medical',title:'First aid essentials',updated:'2024-01',summary:'The interventions that save lives in the first minutes: bleeding, airway, CPR, shock.',seeAlso:['trauma-care','medical-escalation'],quickSteps:['Scene safety first: do not become a second casualty. Identify and remove hazards before approaching.','Massive bleeding: apply direct pressure with both hands, do not remove cloths (add on top), and maintain pressure without letting go for at least 10 full minutes.','Airway: unresponsive adult — tilt head back and lift chin. Look, listen and feel for breathing for no more than 10 seconds.','No breathing or only gasping: begin CPR — 30 chest compressions (hard and fast, at least 2 inches deep, 100 to 120 pushes a minute) then 2 rescue breaths. Continue until help arrives or you are physically unable.','Choking in conscious adult: 5 back blows with heel of hand between shoulder blades, then 5 abdominal thrusts (Heimlich). Alternate until cleared or unconscious.'],sections:[{heading:'The order of priorities — bleeding first, then A-B-C',body:['Catastrophic haemorrhage → Airway → Breathing → Circulation. Control severe bleeding before anything else.','Once bleeding is controlled, open the airway, confirm breathing, and begin CPR only if the person is unresponsive and not breathing normally.']},{heading:'Tourniquet use',body:['Use a tourniquet for extremity (limb) bleeding that cannot be controlled by pressure alone. Apply 2–3 inches (5–7 cm) above the wound. Tighten until bleeding stops.','Write the time of application on the skin or tourniquet. Never remove in the field.','Improvised tourniquet: a belt or strip of cloth twisted with a stick works. It must be 1.5–2 inches (4–5 cm) wide to avoid nerve damage.']},{heading:'Shock',body:['Signs: pale, cold, clammy skin; rapid weak pulse; rapid breathing; anxiety or confusion.','Treatment: lay the person flat, elevate legs 12 inches if no spinal injury, keep warm, do not give fluids by mouth.','Act fast: shock can progress to death. Keep the person talking, monitor breathing, and call for help immediately.']}],sources:[{label:'American Red Cross — First Aid',url:'https://www.redcross.org/take-a-class/first-aid'},{label:'Stop the Bleed',url:'https://www.stopthebleed.org'}]},
  {slug:'signaling-rescue',category:'signaling',title:'Signaling for rescue',updated:'2024-01',summary:'How to make yourself visible and findable to rescuers on land, air or water.',seeAlso:['navigation','radio-comms'],quickSteps:['Stay put unless staying puts you in immediate danger. Rescuers search last known position first.','Three of anything is a universal distress signal — three whistle blasts, three fires, three shots. Repeat at regular intervals.','Signal mirror is the most effective daylight signal — visible for 10+ miles. Aim the reflection toward aircraft by forming a V with two fingers and aligning the mirror flash with it.','Ground-to-air signals: stomp a large X in snow or on a beach (minimum 3m/10ft). Use rocks, logs or clothing to contrast with background.','At night: flash light in groups of three (SOS is 3 short–3 long–3 short in Morse). A strobe light is more visible than a steady beam.'],sections:[{heading:'Signal fire',body:['A fire produces light at night and smoke by day. Build on a hill, clearing or shore — anywhere with open sky.','Daytime: add green or wet leaves for thick white smoke (visible against dark forest). Oil or rubber gives black smoke (visible against snow or a pale sky).','Have the fire pre-built and ready to light the moment you hear aircraft. You may have only 30 seconds.']},{heading:'Whistle and mirror',body:['A plastic pea-less whistle (like a Fox 40) can be heard over a mile in calm conditions and uses almost no energy.','A signal mirror generates a flash visible to aircraft up to 10 miles away even in haze. Aim the flash by looking through the sighting hole and tracking the craft.','Cell phones: even without a network, a 911 call may still route. Keep battery above 20%.']},{heading:'Leaving a trail',body:['If you must move, leave clear signs: arrows made from rocks or sticks pointing your direction of travel; a note in a weatherproof container at your last camp.','Break branches at eye level every 20 metres along your path of travel. This is the fastest method for a search team on foot.']}],sources:[{label:'SAR best practices — NASAR',url:'https://www.nasar.org'},{label:'REI — Signaling for rescue',url:'https://www.rei.com/learn/expert-advice/rescue-signals.html'}]},
  {slug:'navigation',category:'navigation',title:'Navigation without GPS',updated:'2024-01',summary:'How to establish direction and navigate using the sun, stars, natural signs and a map.',seeAlso:['signaling-rescue','shelter-building'],quickSteps:['Establish north before you move: in the northern hemisphere, the sun rises roughly east and sets roughly west. At solar noon (highest point) it is due south.','Analog watch method (northern hemisphere): hold the watch horizontal. Point the hour hand at the sun. The midpoint between the hour hand and 12 o\'clock is south.','Night: find Polaris (North Star) by following the pointer stars at the end of the Big Dipper\'s cup about 5 times their own distance.','Mark your direction with a distant landmark before you walk — a mountain, a distinctive tree. Recheck every 30 minutes in dense cover.','In unfamiliar terrain: follow water downhill. It leads to larger water, settlements, roads and other humans.'],sections:[{heading:'Using a map without a compass',body:['Orient the map to the terrain: rotate it until features on the map (ridges, rivers, roads) align with what you see in front of you.','Take a bearing from known landmarks — triangulation. You are where two bearing lines on the map cross.','Pace count: know how many of your double steps equal 100 metres. Count steps over known ground at home. This lets you measure distance on a map and walk it blind.']},{heading:'Dead reckoning',body:['Dead reckoning: know your starting point, your direction of travel, your speed and elapsed time. Use these to estimate your current position.','It accumulates error — recheck against a landmark every hour and correct your estimate.','In forest: aim off. If your target is at a river crossing, aim deliberately 100m upstream or downstream. When you hit the river, you know which way to turn.']},{heading:'Natural navigation indicators',body:['Moss grows on all sides of trees in damp climates but tends toward north-facing aspects in exposed locations — useful as a rough indicator, not a compass substitute.','In the northern hemisphere, trees on south-facing slopes are more widely spaced with broader canopy. Snow melts first on south slopes.','Prevailing wind: sand dunes, snow ridges and bent trees point downwind — know the prevailing wind direction for your region.']}],sources:[{label:'Tristan Gooley — Natural Navigator',url:'https://www.naturalnavigator.com'},{label:'USGS — Map reading',url:'https://www.usgs.gov/programs/national-geospatial-program/topographic-maps'}]},
  {slug:'foraging',category:'food',title:'Safe foraging and food in the wild',updated:'2024-01',summary:'How to identify safe plants, avoid poisoning yourself, and prioritise effort correctly.',seeAlso:['water-purification','fire-starting'],quickSteps:['Food is last in the survival priority order: shelter > water > fire > signals > food. You can survive 3+ weeks without eating.','Never eat unknown white or yellow berries, plants with milky sap, umbrella-shaped flowers (carrot family), or anything that smells of almonds (cyanide).','Apply the Universal Edibility Test (UET) for any unknown plant: touch, smell, skin contact (15 min), lip contact (3 min), tongue (15 min), chew-no-swallow (15 min), swallow a teaspoon (8 hrs). If no reaction, eat small amounts.','Prioritise calorie-dense, abundant, unambiguous species: dandelion (all parts edible), cattail (roots, pollen), acorns (leach tannins first), pine needles (vitamin C tea).','Insects are high-protein and low-risk: avoid brightly coloured insects. Cook all insects — boiling or roasting kills parasites.'],sections:[{heading:'Three universally safe plants',body:['Dandelion (Taraxacum officinale): all parts edible raw or cooked. Toothed leaves, hollow stem, yellow flowers, white spherical seed head. Grows everywhere.','Cattail (Typha): found at water edges. The cylindrical brown seed head is unmistakeable. Pollen head is edible in spring. Roots are starchy year-round — peel, boil, eat.','Plantain (Plantago major/minor): rosette of oval ribbed leaves. Not the banana — a common lawn weed. Leaves edible raw or cooked. High in vitamins.']},{heading:'Acorns — leaching tannins',body:['Acorns are calorie-rich (fat + starch) but bitter raw from tannins. Leach before eating: crush the kernels, soak in cold water for several hours, changing water until no longer bitter, then dry or cook.','Boiling in multiple changes of water works faster. Cold-water leaching preserves more starch and makes flour.','All oak species produce edible acorns after leaching. White oaks are less bitter than red oaks.']},{heading:'What to absolutely avoid',body:['Hemlock (Conium maculatum): often mistaken for wild carrot. Purple-spotted hollow stem, fine white flowers. Fatal. Smell the crushed leaves — musty, unpleasant.','Deadly nightshade (Atropa belladonna): shiny black berries growing singly, each sitting on a green star-shaped calyx. Fatal.','Mushrooms: even experts make fatal errors. Without formal training, avoid all wild mushrooms in a survival situation.']}],sources:[{label:'USDA Plants Database',url:'https://plants.usda.gov'},{label:'Eat The Weeds',url:'https://www.eattheweeds.com'}]},
  {slug:'radio-comms',category:'comms',title:'Emergency radio communications',updated:'2024-01',summary:'How to use a handheld radio to call for help, monitor alerts, and coordinate with others.',seeAlso:['signaling-rescue','communication-failure'],quickSteps:['NOAA Weather Radio (US) broadcasts on 162.400–162.550 MHz. Keep a battery-powered or hand-crank NOAA radio in your kit.','CB radio Channel 9 is the official emergency channel in the US. FRS/GMRS Channel 1 (462.5625 MHz) is a common default for neighbourhood coordination.','To call for help on VHF marine: Channel 16 is the international distress channel. All vessels monitor it.','When calling Mayday: "MAYDAY MAYDAY MAYDAY, this is [your name/vessel/location], I have [nature of emergency], I need [type of assistance]." Transmit on the designated emergency channel.','Keep your transmission brief. Say your location first, then the emergency, then your callsign or name.'],sections:[{heading:'Radio types and their reach',body:['NOAA Weather Radio: receive-only. Essential for official alerts. Works during power outages on battery.','FRS/GMRS radios: 1–5 mile range in open terrain. No licence for FRS. GMRS requires a US FCC licence. Good for neighbourhood coordination.','Ham radio: requires licence. Much greater range (local repeaters extend to dozens of miles; HF can be global). Provides access to Skywarn and emergency nets.','Satellite communicators (Garmin inReach, SPOT): two-way texting via satellite anywhere in the world. No local infrastructure needed.']},{heading:'Phonetic alphabet and discipline',body:['Use the NATO phonetic alphabet to spell critical information — location names, medication names, callsigns: Alpha Bravo Charlie Delta…','Speak slowly and clearly. Say "over" when you have finished and expect a reply. Say "out" when you have finished the conversation.','Keep emergency channels clear. Brief reports only. Save conversation for a secondary channel.']},{heading:'Hand-crank and solar radios',body:['A hand-crank + solar radio is a core kit item. It operates indefinitely without batteries, can charge a phone via USB, and receives AM/FM/SW/NOAA.','Recommended minimum: a radio with NOAA Weather Alert that activates automatically when a warning is issued for your area.']}],sources:[{label:'ARRL — Amateur radio emergency',url:'https://www.arrl.org/ares'},{label:'FCC — Emergency communications',url:'https://www.fcc.gov/consumers/guides/emergency-communications'},{label:'NOAA Weather Radio',url:'https://www.weather.gov/nwr/'}]},
  {slug:'psychological-resilience',category:'medical',title:'Psychological resilience in crisis',updated:'2024-01',summary:'How to manage fear, panic and decision paralysis during and after an emergency.',seeAlso:['trauma-care','communication-failure'],quickSteps:['Stop, Breathe, Think, Act (SBTA). When panic rises, physically stop what you are doing, take three slow breaths, inventory your situation factually, then act on the highest priority item only.','Assign roles and tasks to everyone capable. Purposeful activity reduces panic and paralysis, including your own.','Acknowledge fear in others: "I know this is scary. What you are feeling is normal." Then redirect: "The next thing we need to do is…"','Communicate your plan clearly even when it is imperfect. Uncertainty is more paralysing than a flawed plan stated with confidence.','After the acute event: eat, drink, sleep as soon as safely possible. Physical depletion accelerates psychological decompensation.'],sections:[{heading:'The survival mindset',body:['Research on survival situations consistently shows that mindset — particularly the will to survive — predicts outcome more than physical skills.','Positive self-talk is not denial. It is directing cognitive resources toward problem-solving instead of threat amplification.','Break the situation into five-minute tasks. The question is not "can I survive this week?" It is "what do I do in the next five minutes?"']},{heading:'Managing others in crisis',body:['Calm is contagious. Lower your voice, slow your movements, and make eye contact. This physiologically down-regulates people around you.','Children look to adults for cues. A calm adult presence reduces acute stress response in children more than any reassurance.','Identify and gently neutralise panic-spreaders. Give them a task that removes them from the group temporarily.']},{heading:'Post-crisis: acute stress and grief',body:['Acute stress responses (flashbacks, hypervigilance, difficulty sleeping) in the first 30 days are normal. They do not predict PTSD.','Seek professional support if symptoms persist beyond 30 days, worsen, or prevent functioning.','Reconnecting with community — even briefly — is one of the strongest predictors of recovery after disaster.']}],sources:[{label:'SAMHSA — Disaster mental health',url:'https://www.samhsa.gov/find-help/disaster-distress-helpline'},{label:'Psychology Today — Crisis resilience',url:'https://www.psychologytoday.com'}]},
  {slug:'cpr-guide',category:'medical',title:'CPR — adult, child and infant',updated:'2024-01',summary:'Step-by-step CPR for unresponsive, non-breathing victims. No training required to try — imperfect CPR saves lives.',seeAlso:['first-aid','medical-escalation'],quickSteps:['Confirm the scene is safe. Tap the person\'s shoulders firmly and shout "Are you OK?"','Call 911 (or have someone call) before starting. Put the phone on speaker.','Place the heel of one hand on the centre of the chest (lower half of the breastbone). Place the second hand on top. Lock your fingers.','Push down hard and fast: at least 2 inches (5 cm) deep, 100–120 compressions per minute (think of the song "Stayin\' Alive"). Allow full chest recoil between compressions.','After 30 compressions: tilt the head back, lift the chin, pinch the nose, seal your mouth over theirs, and give 2 rescue breaths — each over 1 second, enough to see the chest rise.','Continue 30:2 cycles until an AED arrives, emergency services take over, the person starts breathing normally, or you are physically unable to continue.'],sections:[{heading:'Compression-only CPR (hands only)',body:['If you are untrained or unwilling to give rescue breaths, continuous chest compressions alone are effective for the first few minutes of cardiac arrest.','Push hard and fast in the centre of the chest without stopping. This is better than doing nothing — do not wait.','Compression-only CPR is equally effective as standard CPR for witnessed adult cardiac arrest. For children and drowning victims, rescue breaths are more important — use 30:2 if you can.']},{heading:'Children (1 year to puberty)',body:['Procedure is the same as adults. Use one hand only for smaller children to avoid too much depth.','Compression depth: 2 inches (5 cm) or at least one-third of the chest depth.','For infants (under 1 year): wrap both hands around the chest and press with both thumbs side by side on the centre of the chest, just below the nipple line. If you cannot do that, use the heel of one hand. Push down about 1.5 inches (4 cm).']},{heading:'AED use',body:['Power on the AED and follow the voice prompts exactly. It will tell you everything.','Apply pads as shown in the diagram: one below the right collarbone, one on the left side below the armpit. Dry the chest if wet.','Ensure no one is touching the person before the shock is delivered — shout "Clear!" and visually confirm before pressing the shock button.','After the shock, immediately resume CPR. The AED will prompt you when to stop and analyse again.']}],sources:[{label:'American Heart Association — CPR',url:'https://cpr.heart.org'},{label:'Red Cross — CPR steps',url:'https://www.redcross.org/take-a-class/cpr'}]},
  {slug:'bites-stings',category:'medical',title:'Bites, stings and envenomation',updated:'2024-01',summary:'First aid for snake bites, bee stings, severe allergic reactions, and tick removal.',seeAlso:['first-aid','medical-escalation'],quickSteps:['Snake bite: keep the person still and calm. Remove jewellery and tight clothing near the bite. Keep the bitten limb below heart level. Get to a hospital — antivenom is the definitive treatment.','Do NOT cut, suck, tourniquet, apply electricity or ice to a snake bite. These cause harm without helping.','Bee/wasp sting with no allergy: remove the stinger by scraping sideways with a card or fingernail (never squeeze). Apply a cold compress for pain.','Severe allergic reaction (anaphylaxis): adrenaline (epinephrine) auto-injector if prescribed, then call 911. Signs: throat swelling, difficulty breathing, hives, sudden drop in consciousness.','Tick removal: grasp the tick as close to the skin as possible with fine-tipped tweezers. Pull upward steadily — do not twist. Clean the site with alcohol. Do not crush the tick.'],sections:[{heading:'Identifying dangerous vs harmless snakes',body:['In North America: triangular head, elliptical pupils, heat pit between eye and nostril indicate a pit viper (rattlesnake, copperhead, cottonmouth). Coral snakes are slender with red-yellow-black bands ("Red touches yellow, kill a fellow").','Rule: treat all unknown snake bites as potentially venomous. Even non-venomous bites can cause infection.','Photograph the snake if safe to do so without approaching it. This helps medical staff identify treatment needed.','Time is critical with venom — do not delay transport to treat symptoms beyond basic first aid.']},{heading:'Anaphylaxis — act immediately',body:['Anaphylaxis can be fatal within minutes. Act before you are sure.','If prescribed: use the epinephrine auto-injector (EpiPen) into the outer thigh, through clothing if needed. Hold it in place for as long as the label on the injector says (3 to 10 seconds, depending on the brand).','After epinephrine: call 911 even if the person feels better. The reaction can return (biphasic anaphylaxis) in 1–12 hours.','Position: lie the person flat with legs elevated unless breathing is easier sitting up. If unconscious, recovery position.']},{heading:'Tick-borne illness prevention',body:['After outdoor activity: check the whole body including scalp, groin, armpits and behind ears.','A tick usually has to be attached for more than 24 hours to transmit Lyme disease. Daily checks and prompt removal are highly effective prevention.','After removing a tick: watch for a bull\'s-eye rash, fever, fatigue or joint pain in the following weeks. If these appear, seek medical care and mention the tick bite.','Dispose of removed ticks in alcohol, sealed bag, or by flushing. Never crush with fingers.']}],sources:[{label:'CDC — Venomous snakes',url:'https://www.cdc.gov/niosh/topics/snakes'},{label:'American College of Allergy — Anaphylaxis',url:'https://acaai.org/allergies/anaphylaxis'},{label:'CDC — Tick removal',url:'https://www.cdc.gov/ticks/removing_a_tick.html'}]},
  {slug:'hypothermia-frostbite',category:'medical',title:'Hypothermia and frostbite',updated:'2024-01',summary:'Recognising and treating dangerous cold injuries before they become fatal.',seeAlso:['extreme-heat-cold','shelter-building','first-aid'],quickSteps:['Hypothermia — suspect it in anyone who is cold AND confused, shivering uncontrollably, stumbling, or losing consciousness.','Move the person to shelter. Remove wet clothing. Insulate the whole body including the head. Warm the core first (torso, neck, groin, armpits) — not the extremities.','For mild hypothermia (shivering, confused but responsive): warm beverages if the person is fully conscious. Body-to-body warmth under insulation.','For severe hypothermia (not shivering, unconscious, stiff): handle gently — sudden movement can trigger cardiac arrest. Keep horizontal, insulate, and evacuate urgently.','Frostbite — do not rewarm if there is any risk of re-freezing. Walking on frozen feet is safer than thawed, refrozen feet.','Rewarm frostbite only if evacuation is not imminent: immerse in gently moving water at 37–39°C (98–102°F) for 15–30 minutes until the tissue turns pink-red and soft. This is very painful — give pain relief if available.'],sections:[{heading:'Stages of hypothermia',body:['Mild (32–35°C / 90–95°F): shivering, impaired coordination, pale skin, confusion. The person still generates body heat. Warm, dry, insulate — recovery is straightforward.','Moderate (28–32°C / 82–90°F): shivering stops (a danger sign), increasing confusion or sleepiness, heart rhythm may become abnormal. Medical evacuation required.','Severe (below 28°C / 82°F): unconscious, rigid muscles, barely detectable pulse. Can appear dead. Never declare death from hypothermia until warm and dead ("you\'re not dead until you\'re warm and dead"). Continue resuscitation.']},{heading:'Frostbite: assessment and care',body:['Frostnip (superficial): skin is red or pale, cold, tingling or numb — not frozen, and no blisters. Warm with body heat. Full recovery expected. Blisters mean frostbite, not frostnip.','Superficial frostbite: skin is white/grey, firm on the surface but soft underneath. Rewarm actively (see above). Blisters form after rewarming — do not break them.','Deep frostbite: tissue is completely hard, cold and white or mottled. This requires hospital care. Keep frozen until definitive care is available. Avoid pressure and friction on the affected area.','After rewarming: elevate the limb, loosely bandage with clean dry material between toes/fingers. Do not walk on rewarmed feet if avoidable.']},{heading:'Prevention',body:['The wet-cold combination is more dangerous than dry cold. Prioritise staying dry over staying warm.','Layer clothing: moisture-wicking base layer, insulating mid-layer, wind/waterproof outer shell. Avoid cotton next to skin.','Identify early warning signs in yourself and others: numbness, clumsiness, slurred speech. Act on them before they worsen.','Calorie and fluid intake are critical in the cold. Dehydration and starvation accelerate hypothermia.']}],sources:[{label:'Wilderness Medical Society — Cold injuries',url:'https://www.wms.org'},{label:'CDC — Hypothermia',url:'https://www.cdc.gov/disasters/winter/staysafe/hypothermia.html'}]},
  {slug:'trauma-care',category:'medical',title:'Trauma care and wound management',updated:'2024-01',summary:'Managing serious injuries when emergency services cannot arrive quickly: bleeding, fractures, burns, impalement.',seeAlso:['first-aid','medical-escalation'],quickSteps:['Severe bleeding: apply direct pressure. If a limb — tourniquet 2–3 inches above the wound, tighten until bleeding stops, write the time.','For impaled objects: do NOT remove. Stabilise the object with improvised padding and bandage around it. Removal causes rapid, uncontrollable bleeding.','Burns: cool immediately with cool running water for 20 minutes. Do not use ice, butter or toothpaste. Cover with a clean non-fluffy material (cling wrap is ideal).','Fracture — improvised splint: pad the limb, apply rigid material (sticks, board) on both sides, bandage firmly. Splint the joint above and below the fracture.','Spinal injury suspicion: do not move the person unless in immediate danger. If you must move them, minimise spinal motion.'],sections:[{heading:'Wound closure and infection prevention',body:['Clean wounds: irrigate copiously with clean water under pressure (a syringe or squeeze bottle). Remove visible debris.','For gaping wounds: bring the edges together with strips of tape (butterfly closures), or strips of clean fabric if no tape is available.','Wound infection signs: increasing warmth, swelling, redness spreading from the wound, pus, red streaks running from the wound (tracking), fever. These require urgent medical care.','Keep wounds covered with the cleanest material available. Change dressings at least daily.']},{heading:'Chest injuries',body:['Open chest wound (sucking chest wound): do NOT seal it airtight. Leave it open to the air, or cover it loosely with a clean dry dressing that lets air out. Use a vented chest seal only if you have one. If breathing gets worse after covering the wound, remove the covering at once.','Tension pneumothorax: worsening breathing difficulty, absent breath sounds on one side, trachea deviated. This is a medical emergency requiring trained needle decompression.','Rib fractures: support the injury with the person\'s arm or a sling. Have the person take deliberate deep breaths regularly despite the pain to prevent lung complications.']},{heading:'Head injuries',body:['Any loss of consciousness, however brief, requires evacuation and evaluation.','Warning signs after head injury: worsening headache, repeated vomiting, seizure, unequal pupils, confusion or unusual behaviour. These indicate serious injury.','Keep the person awake and talking. The old advice of "keep them awake all night" is debated, but assess neurological status regularly.']}],sources:[{label:'Wilderness Medical Society — Field Guide',url:'https://www.wms.org'},{label:'Stop the Bleed',url:'https://www.stopthebleed.org'},{label:'Remote Area Medical',url:'https://www.ramusa.org'}]},
];

